"use client";
import { useRef, type ReactNode } from "react";
import {
  useScrollMotion,
  scrollUnits,
  scrollStage,
  type ScrollMotionProps,
  type ScrollItem,
} from "./scroll-shared";
import { scrollRandom, scrollEase, scrollStagger, scrollLerp } from "./scroll-math";
export interface ScatterClusterItem extends ScrollItem {
  /** Final center in percentage coordinates. */ x?: number;
  y?: number;
  width?: number;
  height?: number;
  rotation?: number;
}
export interface ScatterClusterProps extends ScrollMotionProps {
  items: readonly ScatterClusterItem[];
  children?: ReactNode;
  pileRadius?: number;
  pileScale?: number;
  spread?: number;
  stagger?: number;
}
/** Cards retain their DOM identity while an overlapping pile opens around the central content. */
export function ScatterCluster({
  items,
  children,
  pileRadius = 28,
  pileScale = 0.9,
  spread = 1,
  stagger = 0.25,
  ...props
}: ScatterClusterProps) {
  const root = useRef<HTMLDivElement>(null);
  useScrollMotion(
    root,
    props,
    ({ progress: p, width: w, height: h }) => {
      scrollUnits(root.current!).forEach((el, i) => {
        const item = items[i]!,
          a = (i / items.length) * Math.PI * 2 - Math.PI / 2,
          q = scrollEase(scrollStagger(p, i, items.length, stagger));
        const x = (((item.x ?? 50 + Math.cos(a) * 37) - 50) / 100) * w * spread,
          y = (((item.y ?? 50 + Math.sin(a) * 36) - 50) / 100) * h * spread;
        el.style.width = `${Math.min((w * (item.width ?? 21)) / 100, h * 0.33)}px`;
        el.style.height = `${(h * (item.height ?? 27)) / 100}px`;
        el.style.transform = `translate(-50%,-50%) translate(${scrollLerp((scrollRandom(i) - 0.5) * pileRadius * 2, x, q)}px,${scrollLerp((scrollRandom(i, 2) - 0.5) * pileRadius * 2, y, q)}px) rotate(${scrollLerp((scrollRandom(i, 3) - 0.5) * 26, item.rotation ?? 0, q)}deg) scale(${scrollLerp(pileScale, 1, q)})`;
      });
      const text = root.current!.querySelector<HTMLElement>("[data-scroll-center]")!;
      text.style.opacity = String(scrollEase(p));
      text.style.transform = `scale(${0.92 + 0.08 * p})`;
    },
    `${items.map((x) => [x.id, x.x, x.y, x.width, x.height, x.rotation].join(":")).join(",")}:${pileRadius}:${pileScale}:${spread}:${stagger}`,
  );
  return (
    <div
      ref={root}
      data-scroll-animation="scatter-cluster"
      className={props.className}
      style={{ ...scrollStage, ...props.style }}
    >
      <div
        data-scroll-center=""
        style={{
          position: "absolute",
          inset: "28% 27%",
          display: "grid",
          placeContent: "center",
          textAlign: "center",
        }}
      >
        {children}
      </div>
      {items.map((item) => (
        <div
          key={item.id}
          data-scroll-unit={item.id}
          className={item.className}
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            width: `${item.width ?? 21}%`,
            height: `${item.height ?? 27}%`,
            borderRadius: 14,
            overflow: "hidden",
            ...item.style,
          }}
        >
          {item.content}
        </div>
      ))}
    </div>
  );
}
